import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BY72S51x.js";const d="/aibutler/docs-versions/v1.1.9/img/settings-models.png",l="/aibutler/docs-versions/v1.1.9/img/persona-ai.png",b=JSON.parse('{"title":"接入模型","description":"","frontmatter":{},"headers":[],"relativePath":"guide/models.md","filePath":"guide/models.md"}'),i={name:"guide/models.md"};function s(n,e,p,h,c,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="接入模型" tabindex="-1">接入模型 <a class="header-anchor" href="#接入模型" aria-label="Permalink to &quot;接入模型&quot;">​</a></h1><p>人格要接上 AI 模型才能思考和说话。有两条路：<strong>Claude 订阅</strong>，或者<strong>自己的 API Key</strong>。两条可以同时开着，每个人格各选各的。</p><div class="tip custom-block"><p class="custom-block-title">不会配？</p><p>直接问人格：「我有一个 DeepSeek 的 key，怎么接？」它会告诉你每一步点哪里。</p></div><h2 id="两个地方-各管一件事" tabindex="-1">两个地方，各管一件事 <a class="header-anchor" href="#两个地方-各管一件事" aria-label="Permalink to &quot;两个地方，各管一件事&quot;">​</a></h2><table tabindex="0"><thead><tr><th>在哪</th><th>管什么</th></tr></thead><tbody><tr><td><strong>系统设置</strong>（主窗口右上角「设置」）</td><td>存「钥匙」：Claude 订阅、API Key。存着不等于在用。</td></tr><tr><td><strong>人格管理</strong> → 某个人格 → 「AI」页</td><td>这个人格用哪把钥匙、哪个引擎、哪个模型。</td></tr></tbody></table><p>先在系统设置里存好，再到人格那边选用。</p><h2 id="方式一-claude-订阅" tabindex="-1">方式一：Claude 订阅 <a class="header-anchor" href="#方式一-claude-订阅" aria-label="Permalink to &quot;方式一：Claude 订阅&quot;">​</a></h2><p>有 Claude Pro 或 Max 订阅，就能让人格用订阅来跑。</p><ol><li>打开系统设置 →「模型服务」→「Claude 订阅」，点「开启」。</li><li>确认后会下载 Anthropic 的 Claude Agent SDK（约 110 MB），下载完点「立即重启」。</li><li>重启后点「登录 Claude」，在浏览器里登录授权。</li><li>看到「已开启并登录」就好了。</li></ol><p>然后到人格的「AI」页，「接入方式」选「用订阅账号」。</p><h2 id="方式二-api-key" tabindex="-1">方式二：API Key <a class="header-anchor" href="#方式二-api-key" aria-label="Permalink to &quot;方式二：API Key&quot;">​</a></h2><h3 id="存一把-key" tabindex="-1">存一把 Key <a class="header-anchor" href="#存一把-key" aria-label="Permalink to &quot;存一把 Key&quot;">​</a></h3><p>打开系统设置 →「模型服务」→「API 凭据」，点「＋ 加一条」，先点你用的那家：</p><p><img src="'+d+'" alt="系统设置里的 API 凭据：先点厂家"></p><p>列表里有 Claude、OpenAI、Google Gemini、千问（大陆 / 国际）、豆包、DeepSeek、Kimi、智谱 GLM、MiniMax、xAI Grok、Mistral。点了之后地址自动填好，你只要把服务商给的 Key 粘进去。不在列表里的（比如各种网关），点「其他 · 自己填地址」，填上网关给的地址和 Key，程序会自己试出该走哪种接口，显示「识别为 …，点保存生效」。</p><p>填完点「保存」，再点「测试」确认能连上。可以存多条。勾了「默认」的那条，是人格没选凭据、或选的那条被删掉时用的。</p><h3 id="让人格用它" tabindex="-1">让人格用它 <a class="header-anchor" href="#让人格用它" aria-label="Permalink to &quot;让人格用它&quot;">​</a></h3><p>新建人格时，接入方式选用 Key，再在「要多聪明?」里点一档：「最强 · 很贵」「强」「日常 · 推荐」「省钱」。程序当场在这把 Key 上试出这一档能用的模型；这把 Key 上已经有人格在用的模型，会标「这把 key 上用过」。想自己指定型号，展开「自己选型号」。豆包的模型要先在它官网逐个开通，所以豆包不分档，直接在模型下拉里选一个你开通了的，程序在你的 Key 上试一下。模型下拉里只列能聊天的模型，画图、视频这类不会出现。</p><p>已经建好的人格，到人格管理 → 这个人格 →「AI」页改：</p><ol><li><strong>接入方式</strong>：选「用系统设置里存的 key」，再选是哪一条。</li><li><strong>引擎</strong>：一般选「Butler 引擎（多模型）」。</li><li><strong>模型</strong>：从下拉里选；列表里没有的，选「其它 · 手动输入模型名」自己填。</li></ol><p><img src="'+l+'" alt="人格的「AI」页"></p><p>改完要重新打开这个人格才生效。</p><div class="tip custom-block"><p class="custom-block-title">手填模型名的写法</p><p>从下拉里选的模型名已经带好了前缀，不用管。手填时：走 OpenAI 兼容接口的（千问、豆包、Kimi 和大多数网关）前面加 <code>compat/</code>，如 <code>compat/qwen-plus</code>；OpenAI 官方前面加 <code>openai/</code>；Claude 直接写型号。不确定就先点「测试」，或者问人格。</p></div><h3 id="在顶栏直接换" tabindex="-1">在顶栏直接换 <a class="header-anchor" href="#在顶栏直接换" aria-label="Permalink to &quot;在顶栏直接换&quot;">​</a></h3><p>想常换模型，打开系统设置 →「通用」→「快速切换模型」，勾「在顶栏显示」。主窗口人格名字右边会出现「key · 模型 ▾」，点开就能给当前人格换 Key 和模型。换 Key 时人格会先把手头的对话存进记忆，再重新打开。</p><h2 id="两种引擎有什么区别" tabindex="-1">两种引擎有什么区别 <a class="header-anchor" href="#两种引擎有什么区别" aria-label="Permalink to &quot;两种引擎有什么区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Butler 引擎（多模型）</th><th>Claude Code</th></tr></thead><tbody><tr><td>是什么</td><td>全能管家自带的</td><td>Anthropic 官方的 Claude Agent SDK</td></tr><tr><td>能接的模型</td><td>Claude、OpenAI、国内大模型、各种网关</td><td>只有 Claude</td></tr><tr><td>什么时候用</td><td>用 API Key 时的默认选择</td><td>用 Claude 订阅时自动用它</td></tr></tbody></table><p>用订阅的人格固定走 Claude Code；用 Key 的人格两种都能选，「引擎」这一项只有装了 Claude 订阅组件后才会出现。</p><h2 id="联网搜索" tabindex="-1">联网搜索 <a class="header-anchor" href="#联网搜索" aria-label="Permalink to &quot;联网搜索&quot;">​</a></h2><p>用 Butler 引擎时，人格默认用模型自带的搜索（有的模型没有）。搜不了或想换，见 <a href="/aibutler/docs-versions/v1.1.9/guide/search.html">联网搜索</a>。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>人格说「还没选模型，暂时无法回复」</strong> 去人格管理 → 这个人格 →「AI」页选一个模型。</p><p><strong>报 401 或「key 不对」</strong> 系统设置里那条 Key 点「测试」。不通就重新复制粘贴一遍 Key，注意前后不要带空格。</p><p><strong>报 400，有时好有时坏</strong> 多半是网关或服务商那边临时拒收，等一会儿再发。一直这样，换一条线路试试，或者把报错原文发给人格让它帮你看。</p><p><strong>想让几个人格用不同的模型</strong> 每个人格的「AI」页各选各的，互不影响。</p>',35)])])}const g=t(i,[["render",s]]);export{b as __pageData,g as default};
